//! Computes the micro:bit firmware's expected bytes with the `std` build of
//! rullst-iot and writes `../firmware/src/expected.rs`. The output depends only
//! on rullst-iot, fixed keys and the fixed image, so CI reruns this and fails
//! when the checked-in file differs.

use ed25519_dalek::{Signer, SigningKey};
use rullst_iot::{
    AnomalyDetector, AnomalyState, CoapMessageType, CoapMethod, CoapRequest, DigitalTwin,
    I2cHelper, ModbusFrame, MqttPublish, MqttQos, OtaManifest, SensorTelemetry,
};
use std::{fmt::Write as _, fs, path::Path};

#[path = "../../firmware/image.rs"]
mod image;

fn bytes(out: &mut String, name: &str, data: &[u8]) {
    writeln!(out, "pub const {name}: &[u8] = &[").unwrap();
    for chunk in data.chunks(12) {
        let line: Vec<String> = chunk.iter().map(|b| format!("0x{b:02x},")).collect();
        writeln!(out, "    {}", line.join(" ")).unwrap();
    }
    out.push_str("];\n");
}

fn main() {
    let mut out = String::from(
        "// @generated by .github/fixtures/iot-microbit-v2/vectors (rullst-iot with std).\n\
         // Do not edit: `cargo run --locked --manifest-path ../vectors/Cargo.toml`.\n\n",
    );

    // ---- MQTT 5 PUBLISH ----
    let mqtt_readme = MqttPublish::reliable(
        "factory/line-1/temperature",
        b"24.5".to_vec(),
        MqttQos::AtLeastOnce,
        7,
    )
    .unwrap()
    .encode()
    .unwrap();
    bytes(&mut out, "MQTT_README_QOS1", &mqtt_readme);
    let mqtt_retained = MqttPublish::new("sensors/microbit-v2/temp", br#"{"t":23.75}"#.to_vec())
        .unwrap()
        .retained(true)
        .encode()
        .unwrap();
    bytes(&mut out, "MQTT_QOS0_RETAINED", &mqtt_retained);
    let long_payload: Vec<u8> = (0..200u32).map(|i| (i * 7) as u8).collect();
    let mqtt_qos2 = MqttPublish::reliable("a/b", long_payload, MqttQos::ExactlyOnce, 0xBEEF)
        .unwrap()
        .duplicate(true)
        .unwrap()
        .encode()
        .unwrap();
    bytes(&mut out, "MQTT_QOS2_DUP_200B", &mqtt_qos2);

    // ---- CoAP ----
    let coap_readme = CoapRequest::new(
        CoapMessageType::Confirmable,
        CoapMethod::Post,
        42,
        [0x01, 0x02],
    )
    .unwrap()
    .path_segment("telemetry")
    .unwrap()
    .content_format(50)
    .payload(br#"{"temperature":24.5}"#.to_vec())
    .unwrap()
    .encode()
    .unwrap();
    bytes(&mut out, "COAP_README_POST", &coap_readme);
    let coap_get = CoapRequest::new(
        CoapMessageType::NonConfirmable,
        CoapMethod::Get,
        0xA1B2,
        Vec::<u8>::new(),
    )
    .unwrap()
    .path_segment("devices")
    .unwrap()
    .path_segment("microbit-v2-serial-0001")
    .unwrap()
    .path_segment("state")
    .unwrap()
    .encode()
    .unwrap();
    bytes(&mut out, "COAP_NON_GET_3SEG", &coap_get);
    let coap_put = CoapRequest::new(
        CoapMessageType::Confirmable,
        CoapMethod::Put,
        0xFFFF,
        [9u8; 8],
    )
    .unwrap()
    .path_segment("fw")
    .unwrap()
    .content_format(11542)
    .payload(vec![0xAB; 300])
    .unwrap()
    .encode()
    .unwrap();
    bytes(&mut out, "COAP_CON_PUT_CF2B_300B", &coap_put);
    let coap_cf0 = CoapRequest::new(CoapMessageType::Confirmable, CoapMethod::Delete, 1, [0x7f])
        .unwrap()
        .content_format(0)
        .encode()
        .unwrap();
    bytes(&mut out, "COAP_DELETE_CF0", &coap_cf0);

    // ---- Telemetry / frames ----
    let telemetry = SensorTelemetry::new("microbit-v2-01", "temperature", 23.75, 1_762_790_400);
    bytes(
        &mut out,
        "TELEMETRY_JSON",
        &serde_json::to_vec(&telemetry).unwrap(),
    );
    let mut twin = DigitalTwin::new("microbit-v2-01");
    twin.ingest(telemetry.clone());
    twin.ingest(SensorTelemetry::new(
        "microbit-v2-01",
        "light",
        0.125,
        1_762_790_401,
    ));
    bytes(
        &mut out,
        "TWIN_JSON",
        twin.try_to_sync_payload().unwrap().as_bytes(),
    );
    bytes(
        &mut out,
        "MODBUS_READ_17_6B_3",
        &ModbusFrame::read_holding_registers(17, 0x006B, 3),
    );
    bytes(
        &mut out,
        "I2C_READ_19_0F_6",
        &I2cHelper::try_build_read_frame(0x19, 0x0F, 6).unwrap(),
    );

    // ---- Anomaly ----
    let series: [f64; 12] = [
        25.0,
        26.0,
        29.99,
        30.0,
        30.01,
        35.0,
        35.01,
        15.0,
        14.99,
        -1.0e9,
        f64::NAN,
        f64::NEG_INFINITY,
    ];
    let detector = AnomalyDetector::new(25.0, 5.0);
    let states: Vec<u8> = series
        .iter()
        .map(|v| match detector.evaluate(*v) {
            AnomalyState::Normal => 0,
            AnomalyState::Warning => 1,
            AnomalyState::CriticalAnomaly => 2,
        })
        .collect();
    bytes(&mut out, "ANOMALY_STATES", &states);

    // ---- OTA ----
    let key = SigningKey::from_bytes(&[0x42; 32]);
    let wrong_key = SigningKey::from_bytes(&[0x24; 32]);
    bytes(&mut out, "OTA_PUBLIC_KEY", key.verifying_key().as_bytes());
    bytes(
        &mut out,
        "OTA_WRONG_PUBLIC_KEY",
        wrong_key.verifying_key().as_bytes(),
    );
    let firmware = image::firmware_image();
    assert_eq!(firmware.len(), image::FIRMWARE_LEN);
    let manifest = OtaManifest::from_firmware("microbit-v2", "1.1.0", 42, &firmware).unwrap();
    bytes(&mut out, "OTA_FIRMWARE_SHA256", &manifest.firmware_sha256());
    bytes(
        &mut out,
        "OTA_SIGNING_BYTES_42",
        &manifest.signing_bytes().unwrap(),
    );
    for counter in [42u64, 43, 44] {
        let m = OtaManifest::from_firmware("microbit-v2", "1.1.0", counter, &firmware).unwrap();
        let sig = key.sign(&m.signing_bytes().unwrap());
        bytes(&mut out, &format!("OTA_SIG_{counter}"), &sig.to_bytes());
    }
    let wrong_target = OtaManifest::from_firmware("nrf52840-dk", "1.1.0", 42, &firmware).unwrap();
    bytes(
        &mut out,
        "OTA_SIG_WRONG_TARGET",
        &key.sign(&wrong_target.signing_bytes().unwrap()).to_bytes(),
    );
    let tiny = b"tiny-firmware-16";
    bytes(&mut out, "OTA_TINY_FIRMWARE", tiny);
    let tiny_manifest = OtaManifest::from_firmware("microbit-v2", "1.0.1", 7, tiny).unwrap();
    bytes(
        &mut out,
        "OTA_SIG_TINY_7",
        &key.sign(&tiny_manifest.signing_bytes().unwrap()).to_bytes(),
    );

    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../firmware/src/expected.rs");
    fs::write(&path, out).unwrap();
    eprintln!("wrote {}", path.display());
}
